window.IDIOMS = [{"id":"draw-snake-add-feet","idiom":"画蛇添足","pinyin":"huà shé tiān zú","meaning":"事情本来已经做好，却又加上不需要的部分，反而破坏原来的效果，比喻多此一举，弄巧成拙。","misconception":"不是所有补充都有害，关键是多余的添加反而破坏效果。","sourceUrl":"https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=-23&la=0&webMd=1","sourceName":"教育部《成语典》"},{"id":"wait-by-stump","idiom":"守株待兔","pinyin":"shǒu zhū dài tù","meaning":"偶然得到一次好处，就不再努力，只等同样的好运再来，也用来提醒人不能死守旧办法而不知改变。","misconception":"“株”指树桩；耐心等待合理时机，不一定是这个成语。","sourceUrl":"https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=39&la=0&webMd=1","sourceName":"教育部《成语典》"},{"id":"frog-in-well","idiom":"井底之蛙","pinyin":"jǐng dǐ zhī wā","meaning":"只接触过很小的范围，却以为自己已经了解整个世界，比喻见识狭窄，不知道外面还有更广阔的天地。","misconception":"重点是见识受限，不是说住在某个地方的人一定见识少。","sourceUrl":"https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=380&webMd=1","sourceName":"教育部《成语典》"},{"id":"cover-ears-steal-bell","idiom":"掩耳盗铃","pinyin":"yǎn ěr dào líng","meaning":"明明问题还在，却用办法骗自己，以为自己没有听见或看见，别人也不会发现，结果只是自欺欺人。","misconception":"古代典源写的是盗钟，后来常用“掩耳盗铃”来比喻自欺欺人。","sourceUrl":"https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=-2&la=0&webMd=1","sourceName":"教育部《成语典》"},{"id":"pull-seedlings","idiom":"拔苗助长","pinyin":"bá miáo zhù zhǎng","meaning":"为了让事情快点成功，不顾它本来的发展规律，采用不合适的办法催促，结果没帮上忙，反而造成损害。","misconception":"也作“揠苗助长”，“揠”读 yà；并不是说一切帮助和努力都没有用。","sourceUrl":"https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=56&la=0&webMd=1","sourceName":"教育部《成语典》"},{"id":"mend-sheep-pen","idiom":"亡羊补牢","pinyin":"wáng yáng bǔ láo","meaning":"已经发生损失后，及时找出问题并采取补救办法，避免同样的损失再次发生，说明现在改正仍有意义。","misconception":"“亡”是丢失，“牢”是牲畜圈；补救不能让已经失去的羊自动回来。","sourceUrl":"https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=-484&la=1&webMd=2","sourceName":"教育部《成语典》"},{"id":"play-music-to-ox","idiom":"对牛弹琴","pinyin":"duì niú tán qín","meaning":"向不能理解的人讲道理或说深奥的话，难以得到回应，也提醒说话的人要考虑听众，用合适的方式表达。","misconception":"不要用这个成语骂不懂某件事的人；沟通者也要考虑对象。","sourceUrl":"https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=47&la=0&webMd=1","sourceName":"教育部《成语典》"},{"id":"fox-borrows-tiger-power","idiom":"狐假虎威","pinyin":"hú jiǎ hǔ wēi","meaning":"自己没有那样的威势，却借着有权势者的名头吓唬或欺压别人，让别人误以为自己很有力量。","misconception":"“假”在这里是借助，不是狐狸假扮成老虎。","sourceUrl":"https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=32&la=0&webMd=2","sourceName":"教育部《成语典》"},{"id":"mark-boat-find-sword","idiom":"刻舟求剑","pinyin":"kè zhōu qiú jiàn","meaning":"情况已经发生变化，却仍然照搬原来的办法，不根据新的条件思考和行动，比喻做事死板，不懂变通。","misconception":"剑留在落水处，船会继续移动；问题不在于做标记本身。","sourceUrl":"https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=-43&la=0&webMd=2","sourceName":"教育部《成语典》"},{"id":"feel-parts-of-elephant","idiom":"盲人摸象","pinyin":"máng rén mō xiàng","meaning":"只了解事物的一小部分，就把这部分当作全部，并坚持自己的判断，提醒我们先了解全貌再下结论。","misconception":"寓意是不能以偏概全，不是嘲笑视障者；每个人都可能因信息不全而误判。","sourceUrl":"https://www.eduhk.hk/cle/resources/cep/01/01.htm","sourceName":"香港教育大学：中文成语网上自学教材"},{"id":"pretend-in-orchestra","idiom":"滥竽充数","pinyin":"làn yú chōng shù","meaning":"没有真正的本领，却混在有本领的人中假装会做，也可指拿不好的东西凑数，让人误以为合格。","misconception":"“竽”是一种古代吹奏乐器；正常参加集体活动或正在学习，不等于冒充。","sourceUrl":"https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=54&la=0&webMd=2","sourceName":"教育部《成语典》"},{"id":"bow-reflection-snake","idiom":"杯弓蛇影","pinyin":"bēi gōng shé yǐng","meaning":"把误看的影像当成真的危险，在没有弄清事实时自己吓自己，产生不必要的猜疑和恐惧。","misconception":"杯里并没有真蛇；弓的映像造成误会，不是弓变成了蛇。","sourceUrl":"https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=-49&la=0&webMd=2","sourceName":"教育部《成语典》"},{"id":"idiom-013","idiom":"一石二鸟","pinyin":"yī shí èr niǎo","meaning":"用一块石头打中两只鸟，比喻做一件事情，同时达到两个目的或得到两种好处。","misconception":"","sourceUrl":"https://dict.revised.moe.edu.tw/dictView.jsp?ID=149669&la=0&powerMode=0","sourceName":"教育部《重编国语辞典修订本》"},{"id":"idiom-014","idiom":"一箭双雕","pinyin":"yī jiàn shuāng diāo","meaning":"一支箭射中两只雕，比喻采取一个行动，同时达到两个目的，收到两方面的效果。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-015","idiom":"一举两得","pinyin":"yī jǔ liǎng dé","meaning":"做一件事情就得到两方面的好处，形容一次行动同时带来两种有益的结果。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-016","idiom":"一心一意","pinyin":"yī xīn yī yì","meaning":"把全部心思集中在一件事情上，不分心，也不同时想着别的事情。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-017","idiom":"三心二意","pinyin":"sān xīn èr yì","meaning":"做事情时心思不专一，一会儿想这样，一会儿想那样，拿不定主意或容易分心。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-018","idiom":"七上八下","pinyin":"qī shàng bā xià","meaning":"形容心里紧张、慌乱或担忧，总觉得不踏实，无法安定下来。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-019","idiom":"九牛一毛","pinyin":"jiǔ niú yī máo","meaning":"九头牛身上的一根毛，比喻很大数量中极小的一部分，少得不值得一提。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-020","idiom":"十全十美","pinyin":"shí quán shí měi","meaning":"各个方面都十分完善，没有缺点或不足，形容事物达到了非常完美的程度。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-021","idiom":"百发百中","pinyin":"bǎi fā bǎi zhòng","meaning":"每次射击都能命中目标，形容射击十分准确，也比喻做事很有把握，次次成功。","misconception":"“中”读 zhòng，意思是命中目标。","sourceUrl":"","sourceName":""},{"id":"idiom-022","idiom":"千钧一发","pinyin":"qiān jūn yī fà","meaning":"像一根头发吊着极重的东西，随时可能断裂，比喻情况极其危险，十分紧急。","misconception":"“发”指头发，读 fà；“钧”是古代重量单位。","sourceUrl":"https://www.zdic.net/hans/千钧一发","sourceName":"汉典"},{"id":"idiom-023","idiom":"万众一心","pinyin":"wàn zhòng yī xīn","meaning":"许许多多的人有着共同的目标，像一个人那样齐心协力，团结一致地做事。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-024","idiom":"半途而废","pinyin":"bàn tú ér fèi","meaning":"事情做到一半就停止，不再继续努力，指没有坚持到底而放弃原来的目标。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-025","idiom":"坚持不懈","pinyin":"jiān chí bù xiè","meaning":"始终坚持努力，不因为时间长或遇到困难就松懈下来，形容做事有毅力。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-026","idiom":"锲而不舍","pinyin":"qiè ér bù shě","meaning":"像不断雕刻而不停止那样，坚持努力不肯放弃，比喻有恒心、有毅力。","misconception":"","sourceUrl":"https://dict.concised.moe.edu.tw/dictView.jsp?ID=24836&la=0&powerMode=0","sourceName":"教育部《国语辞典简编本》"},{"id":"idiom-027","idiom":"持之以恒","pinyin":"chí zhī yǐ héng","meaning":"用长久不变的决心坚持做一件事，不只是一时热心，而是能够持续努力。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-028","idiom":"滴水穿石","pinyin":"dī shuǐ chuān shí","meaning":"水滴不停地落下，时间久了能穿透石头，比喻力量虽小，坚持下去也能做成难事。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-029","idiom":"绳锯木断","pinyin":"shéng jù mù duàn","meaning":"用绳子不停地锯木头，日子久了也能锯断，比喻坚持不懈，小力量也能发挥大作用。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-030","idiom":"铁杵成针","pinyin":"tiě chǔ chéng zhēn","meaning":"把粗铁棒磨成细针，比喻只要有恒心、肯下功夫，再难的事情也有做成的可能。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-031","idiom":"愚公移山","pinyin":"yú gōng yí shān","meaning":"传说愚公决心搬走挡路的大山，比喻认定目标后不怕困难，坚持不懈地努力。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-032","idiom":"精卫填海","pinyin":"jīng wèi tián hǎi","meaning":"神话中的精卫鸟不断衔来木石填海，比喻意志坚定，面对艰难也不放弃努力。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-033","idiom":"夸父逐日","pinyin":"kuā fù zhú rì","meaning":"神话中的夸父追赶太阳，常用来形容志向远大、努力追求，也可比喻不自量力。","misconception":"可赞扬追求精神，也可含不自量力之意，需要结合语境理解。","sourceUrl":"","sourceName":""},{"id":"idiom-034","idiom":"女娲补天","pinyin":"nǚ wā bǔ tiān","meaning":"神话中天空破裂、灾害发生，女娲炼出五色石修补天空，帮助人们摆脱灾难。","misconception":"这是神话传说，不是实际发生的科学或历史事件。","sourceUrl":"","sourceName":""},{"id":"idiom-035","idiom":"后羿射日","pinyin":"hòu yì shè rì","meaning":"神话中十个太阳同时出现，炙烤大地，善射的英雄射下九个太阳，为人们解除灾难。","misconception":"这是神话传说，不能把十个太阳同时出现当作真实天文记录。","sourceUrl":"https://dict.revised.moe.edu.tw/dictView.jsp?ID=81297&la=0&powerMode=0","sourceName":"教育部《重编国语辞典修订本》"},{"id":"idiom-036","idiom":"嫦娥奔月","pinyin":"cháng é bēn yuè","meaning":"神话中嫦娥吃下仙药后飞向月亮，从此居住在月宫，成为流传已久的月亮故事。","misconception":"不同版本对服药原因说法不同；这里不指定某一种原因，“奔”读 bēn。","sourceUrl":"https://www.zdic.net/hans/嫦娥奔月","sourceName":"汉典"},{"id":"idiom-037","idiom":"八仙过海","pinyin":"bā xiān guò hǎi","meaning":"传说八位仙人各用自己的法宝渡海，比喻大家各自拿出本领，运用不同办法完成事情。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-038","idiom":"叶公好龙","pinyin":"yè gōng hào lóng","meaning":"叶公喜欢龙的图案，见到真龙却害怕逃走，比喻表面上说喜欢，实际上并不真正喜欢。","misconception":"这里按普通话常用读音读 yè gōng hào lóng；“好”读 hào。","sourceUrl":"https://www.zdic.net/hans/叶公好龙","sourceName":"汉典"},{"id":"idiom-039","idiom":"画龙点睛","pinyin":"huà lóng diǎn jīng","meaning":"传说给画好的龙点上眼睛，龙便飞走，比喻在关键处加上精彩内容，使整体更加生动。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-040","idiom":"龙飞凤舞","pinyin":"lóng fēi fèng wǔ","meaning":"原来形容山势雄伟、奔放，后来多形容书法笔画舒展有力、姿态生动而洒脱。","misconception":"可以赞美书法奔放有力，不一定指字迹潦草。","sourceUrl":"","sourceName":""},{"id":"idiom-041","idiom":"龙腾虎跃","pinyin":"lóng téng hǔ yuè","meaning":"像龙腾飞、虎跳跃一样，形容动作矫健有力，也形容场面热烈、充满活力。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-042","idiom":"生龙活虎","pinyin":"shēng lóng huó hǔ","meaning":"像活跃的龙和虎一样，形容人很有精神、身体有活力，行动十分生动活泼。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-043","idiom":"虎头蛇尾","pinyin":"hǔ tóu shé wěi","meaning":"开头像老虎的头那样有气势，结尾却像蛇尾那样细弱，比喻起初认真，后来草率收场。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-044","idiom":"骑虎难下","pinyin":"qí hǔ nán xià","meaning":"骑在老虎背上难以下来，比喻事情进行到某个地步，即使想停止，也因为处境困难而停不下来。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-045","idiom":"如虎添翼","pinyin":"rú hǔ tiān yì","meaning":"好像老虎又长出了翅膀，比喻原本就有力量的人或事物得到帮助后，变得更加强大。","misconception":"不只用于好事；原有力量变强，也可能使坏人更难对付。","sourceUrl":"","sourceName":""},{"id":"idiom-046","idiom":"调虎离山","pinyin":"diào hǔ lí shān","meaning":"设法让老虎离开它占优势的山林，比喻引诱对方离开有利的位置，再寻找机会对付它。","misconception":"“调”读 diào，意思是调动、引开，不读 tiáo。","sourceUrl":"","sourceName":""},{"id":"idiom-047","idiom":"虎视眈眈","pinyin":"hǔ shì dān dān","meaning":"像老虎盯着猎物一样凶狠地看着，形容心怀恶意，等待机会抢夺或侵害。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-048","idiom":"马到成功","pinyin":"mǎ dào chéng gōng","meaning":"战马一到就取得胜利，形容事情一开始就顺利取得成功，也常用来祝愿别人办事成功。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-049","idiom":"一马当先","pinyin":"yī mǎ dāng xiān","meaning":"一匹马冲在最前面，形容走在前列、勇于领先，也表示主动带头做事。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-050","idiom":"走马观花","pinyin":"zǒu mǎ guān huā","meaning":"骑着马匆匆看花，比喻观察或了解事物不够仔细，只看到了表面的大概情况。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-051","idiom":"老马识途","pinyin":"lǎo mǎ shí tú","meaning":"老马认识曾经走过的路，比喻有经验的人熟悉情况，能在遇到问题时提供帮助。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-052","idiom":"指鹿为马","pinyin":"zhǐ lù wéi mǎ","meaning":"指着鹿硬说是马，比喻故意把事实说反，混淆是非，使人难以分清真相。","misconception":"重点是故意颠倒事实，不是无意中认错东西。","sourceUrl":"","sourceName":""},{"id":"idiom-053","idiom":"惊弓之鸟","pinyin":"jīng gōng zhī niǎo","meaning":"被弓箭惊吓过的鸟，听到弓声便害怕，比喻受过惊吓后，遇到一点动静就十分恐惧的人。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-054","idiom":"笨鸟先飞","pinyin":"bèn niǎo xiān fēi","meaning":"飞得慢的鸟先出发，比喻觉得自己能力不足的人，比别人更早开始准备，付出更多努力。","misconception":"常用来表示谦虚或自我勉励，不应用来给别人贴上“笨”的标签。","sourceUrl":"","sourceName":""},{"id":"idiom-055","idiom":"鸟语花香","pinyin":"niǎo yǔ huā xiāng","meaning":"鸟儿鸣叫，花朵散发香气，形容春天或自然环境中的景色美好、生机勃勃。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-056","idiom":"鹤立鸡群","pinyin":"hè lì jī qún","meaning":"像鹤站在鸡群中一样显眼，比喻一个人的仪表或才能在周围的人中十分突出。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-057","idiom":"鸡飞狗跳","pinyin":"jī fēi gǒu tiào","meaning":"鸡受惊飞起，狗慌忙跳窜，形容受到惊扰后乱作一团、不得安宁的样子。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-058","idiom":"鸡犬不宁","pinyin":"jī quǎn bù níng","meaning":"连鸡和狗都不能安静下来，形容骚扰很严重，使周围的人和生活都不得安宁。","misconception":"","sourceUrl":"","sourceName":""},{"idiom":"闻鸡起舞","pinyin":"wén jī qǐ wǔ","meaning":"听到鸡叫就起床练剑，比喻有志向的人抓紧时间，勤奋学习或锻炼。","misconception":"这里的“舞”指舞剑练武，不是听见鸡叫就跳舞。","id":"idiom-059","sourceUrl":"","sourceName":""},{"idiom":"狗急跳墙","pinyin":"gǒu jí tiào qiáng","meaning":"狗被逼急了也会跳墙，比喻人走投无路时，不顾后果地采取极端行动。","misconception":"通常含有贬义，不用来赞扬勇敢克服困难。","id":"idiom-060","sourceUrl":"","sourceName":""},{"idiom":"兔死狐悲","pinyin":"tù sǐ hú bēi","meaning":"兔子死了，狐狸感到悲伤，比喻因同类遭遇不幸，担心自己而感到悲伤。","misconception":"重点是因同类的不幸而悲伤，不是泛指任何伤心。","id":"idiom-061","sourceUrl":"","sourceName":""},{"idiom":"胆小如鼠","pinyin":"dǎn xiǎo rú shǔ","meaning":"胆子小得像老鼠一样，形容人十分胆小，遇到事情容易害怕。","misconception":"","id":"idiom-062","sourceUrl":"","sourceName":""},{"idiom":"鼠目寸光","pinyin":"shǔ mù cùn guāng","meaning":"像老鼠一样只能看见眼前很近的地方，比喻目光短浅，缺少长远考虑。","misconception":"形容的是见识和眼光，不是说一个人的视力不好。","id":"idiom-063","sourceUrl":"","sourceName":""},{"idiom":"鱼目混珠","pinyin":"yú mù hùn zhū","meaning":"把鱼眼睛混在珍珠里面冒充珍珠，比喻用假的东西冒充真的东西。","misconception":"重点是以假充真，不是说真假双方互相弄混了。","id":"idiom-064","sourceUrl":"","sourceName":""},{"idiom":"如鱼得水","pinyin":"rú yú dé shuǐ","meaning":"像鱼回到水里一样，比喻得到合适的环境或帮助，能够自在地发挥本领。","misconception":"","id":"idiom-065","sourceUrl":"","sourceName":""},{"idiom":"缘木求鱼","pinyin":"yuán mù qiú yú","meaning":"爬到树上去找鱼，比喻方向或方法不对，无论怎样努力也达不到目的。","misconception":"“缘木”是爬树，不是在树木旁边找鱼。","id":"idiom-066","sourceUrl":"","sourceName":""},{"idiom":"鱼跃龙门","pinyin":"yú yuè lóng mén","meaning":"传说鲤鱼跃过龙门就会变成龙，比喻考试得中、地位上升或取得重大成功。","misconception":"鱼跃过龙门变成龙是传说，不是鱼类真实的生长过程。","id":"idiom-067","sourceUrl":"","sourceName":""},{"idiom":"瓮中捉鳖","pinyin":"wèng zhōng zhuō biē","meaning":"在陶制的大缸里捉鳖，比喻要捉的对象已无处可逃，抓获它很容易。","misconception":"","id":"idiom-068","sourceUrl":"","sourceName":""},{"idiom":"螳臂当车","pinyin":"táng bì dāng chē","meaning":"螳螂举起前肢想挡住车子，比喻高估自己的力量，硬要阻挡强大的事物。","misconception":"通常用来批评不自量力，不能直接当作赞扬勇敢的词。","id":"idiom-069","sourceUrl":"https://www.zdic.net/hans/螳臂当车","sourceName":"汉典：螳臂当车"},{"idiom":"金蝉脱壳","pinyin":"jīn chán tuō qiào","meaning":"像蝉脱去外壳那样，保留原来的表面样子来迷惑对方，自己趁机脱身。","misconception":"重点是用假象掩护脱身，不是简单地逃跑。","id":"idiom-070","sourceUrl":"https://www.zdic.net/hans/金蝉脱壳","sourceName":"汉典：金蝉脱壳"},{"idiom":"蚕食鲸吞","pinyin":"cán shí jīng tūn","meaning":"像蚕吃桑叶、鲸吞食物一样，比喻逐步侵占或一下子大量吞并别人的土地等。","misconception":"通常指侵占、吞并，不是赞扬吃东西的本领。","id":"idiom-071","sourceUrl":"","sourceName":""},{"idiom":"狼吞虎咽","pinyin":"láng tūn hǔ yàn","meaning":"像狼和老虎吞食东西一样，形容吃东西又急又猛，没有细嚼慢咽。","misconception":"","id":"idiom-072","sourceUrl":"","sourceName":""},{"idiom":"狼狈为奸","pinyin":"láng bèi wéi jiān","meaning":"比喻坏人相互勾结，彼此配合，一起做坏事，是带有贬义的说法。","misconception":"不能用来称赞朋友之间合作得好。","id":"idiom-073","sourceUrl":"","sourceName":""},{"idiom":"蛛丝马迹","pinyin":"zhū sī mǎ jì","meaning":"像细小的蛛丝和留下的脚印一样，比喻能用来追查事情的细微线索。","misconception":"","id":"idiom-074","sourceUrl":"","sourceName":""},{"idiom":"蜂拥而至","pinyin":"fēng yōng ér zhì","meaning":"像一群蜜蜂拥在一起那样涌过来，形容许多人同时向一个地方赶来。","misconception":"","id":"idiom-075","sourceUrl":"","sourceName":""},{"idiom":"蜻蜓点水","pinyin":"qīng tíng diǎn shuǐ","meaning":"像蜻蜓轻轻碰一下水面就飞开，比喻做事只接触表面，没有深入下去。","misconception":"用来评价做事时，通常批评做得不深入。","id":"idiom-076","sourceUrl":"","sourceName":""},{"idiom":"螳螂捕蝉","pinyin":"táng láng bǔ chán","meaning":"螳螂只顾捕蝉，没发现身后的危险，比喻只图眼前利益，不顾隐藏的后患。","misconception":"常与“黄雀在后”连用，重点是忽略身后的危险。","id":"idiom-077","sourceUrl":"https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=1096&la=0&webMd=2","sourceName":"教育部《成语典》：螳螂捕蝉"},{"idiom":"门可罗雀","pinyin":"mén kě luó què","meaning":"门前冷清得可以张网捉雀，形容来往的人很少，或前来拜访的人很少。","misconception":"形容冷清，不是说门前鸟多、十分热闹。","id":"idiom-078","sourceUrl":"","sourceName":""},{"idiom":"车水马龙","pinyin":"chē shuǐ mǎ lóng","meaning":"车辆像流水，马匹像长龙，形容车马来往很多，路上繁忙而热闹。","misconception":"","id":"idiom-079","sourceUrl":"","sourceName":""},{"idiom":"人山人海","pinyin":"rén shān rén hǎi","meaning":"人群像山和海一样，形容聚集的人非常多，到处都是人的身影。","misconception":"","id":"idiom-080","sourceUrl":"","sourceName":""},{"idiom":"人声鼎沸","pinyin":"rén shēng dǐng fèi","meaning":"人们说话的声音像锅里的水沸腾一样，形容人声嘈杂，非常热闹。","misconception":"重点是人声喧闹，不是只说人数很多。","id":"idiom-081","sourceUrl":"","sourceName":""},{"idiom":"摩肩接踵","pinyin":"mó jiān jiē zhǒng","meaning":"肩膀挨着肩膀，脚跟碰着脚跟，形容人特别多，彼此挤得很近。","misconception":"“踵”指脚后跟。","id":"idiom-082","sourceUrl":"","sourceName":""},{"idiom":"座无虚席","pinyin":"zuò wú xū xí","meaning":"每个座位都有人坐，没有一个空座位，形容到场的人很多，场面满座。","misconception":"","id":"idiom-083","sourceUrl":"","sourceName":""},{"idiom":"川流不息","pinyin":"chuān liú bù xī","meaning":"像河水流动那样不停，通常形容行人、车辆等来来往往，连续不断。","misconception":"“川”指河流，“息”指停止。","id":"idiom-084","sourceUrl":"","sourceName":""},{"idiom":"络绎不绝","pinyin":"luò yì bù jué","meaning":"行人、车马或船只等一个接着一个到来或经过，前后相连，没有断绝。","misconception":"","id":"idiom-085","sourceUrl":"","sourceName":""},{"idiom":"五光十色","pinyin":"wǔ guāng shí sè","meaning":"形容色彩丰富鲜艳，光泽绚丽夺目，让人看起来觉得非常漂亮。","misconception":"“五”和“十”不表示固定数量。","id":"idiom-086","sourceUrl":"","sourceName":""},{"idiom":"五颜六色","pinyin":"wǔ yán liù sè","meaning":"形容颜色种类很多，各种颜色混合在一起，显得丰富而多样。","misconception":"不是正好五种或六种颜色。","id":"idiom-087","sourceUrl":"","sourceName":""},{"idiom":"姹紫嫣红","pinyin":"chà zǐ yān hóng","meaning":"形容各种颜色的花朵鲜艳美丽，常用来描绘百花盛开时的美好景色。","misconception":"通常形容花朵，不宜随意形容任何彩色物品。","id":"idiom-088","sourceUrl":"","sourceName":""},{"idiom":"春暖花开","pinyin":"chūn nuǎn huā kāi","meaning":"春天气候温暖，花儿纷纷开放，形容春天温和、美丽而充满生机的景象。","misconception":"","id":"idiom-089","sourceUrl":"","sourceName":""},{"idiom":"春回大地","pinyin":"chūn huí dà dì","meaning":"春天重新来到大地，寒冷渐渐退去，草木开始生长，到处恢复生机。","misconception":"","id":"idiom-090","sourceUrl":"","sourceName":""},{"idiom":"风和日丽","pinyin":"fēng hé rì lì","meaning":"风吹得温和，阳光明亮，形容天气晴朗暖和，适合欣赏户外景色。","misconception":"","id":"idiom-091","sourceUrl":"","sourceName":""},{"idiom":"风平浪静","pinyin":"fēng píng làng jìng","meaning":"没有风浪，水面很平静；也比喻生活或局势安定，没有波折和冲突。","misconception":"","id":"idiom-092","sourceUrl":"","sourceName":""},{"idiom":"风雨交加","pinyin":"fēng yǔ jiāo jiā","meaning":"风和雨一同袭来，形容天气恶劣，风吹雨打同时发生的情景。","misconception":"","id":"idiom-093","sourceUrl":"","sourceName":""},{"idiom":"狂风暴雨","pinyin":"kuáng fēng bào yǔ","meaning":"猛烈的大风和急骤的大雨，也比喻声势很大、来势迅猛的行动或冲击。","misconception":"","id":"idiom-094","sourceUrl":"","sourceName":""},{"idiom":"倾盆大雨","pinyin":"qīng pén dà yǔ","meaning":"雨水像从盆里倒下来一样，形容雨下得非常大，而且十分急。","misconception":"","id":"idiom-095","sourceUrl":"","sourceName":""},{"idiom":"雷电交加","pinyin":"léi diàn jiāo jiā","meaning":"打雷和闪电一同出现，形容雷声不断、闪电接连划过天空的天气。","misconception":"","id":"idiom-096","sourceUrl":"","sourceName":""},{"idiom":"冰天雪地","pinyin":"bīng tiān xuě dì","meaning":"到处是冰和雪，形容天气十分寒冷，或四周被冰雪覆盖的景象。","misconception":"","id":"idiom-097","sourceUrl":"","sourceName":""},{"idiom":"天寒地冻","pinyin":"tiān hán dì dòng","meaning":"天气非常寒冷，地面也冻住了，形容气温很低、寒冷难耐的情形。","misconception":"","id":"idiom-098","sourceUrl":"","sourceName":""},{"idiom":"天高云淡","pinyin":"tiān gāo yún dàn","meaning":"天空显得高远开阔，云朵稀薄而轻淡，常用来形容晴朗的秋日景色。","misconception":"","id":"idiom-099","sourceUrl":"","sourceName":""},{"idiom":"秋高气爽","pinyin":"qiū gāo qì shuǎng","meaning":"形容秋天天空晴朗高远，空气清新凉爽，让人觉得舒适的天气。","misconception":"","id":"idiom-100","sourceUrl":"","sourceName":""},{"idiom":"落叶归根","pinyin":"luò yè guī gēn","meaning":"落下的树叶回到树根旁，比喻长期在外的人，最终回到自己的故乡。","misconception":"重点是回归故乡，不是指所有物品回到原处。","id":"idiom-101","sourceUrl":"","sourceName":""},{"idiom":"枝繁叶茂","pinyin":"zhī fán yè mào","meaning":"树木的枝条繁多，叶子茂密，形容植物长得旺盛、充满生机。","misconception":"","id":"idiom-102","sourceUrl":"","sourceName":""},{"idiom":"绿树成荫","pinyin":"lǜ shù chéng yīn","meaning":"绿色树木枝叶茂密，连成一片可以遮挡阳光的树荫，形容树木繁盛。","misconception":"","id":"idiom-103","sourceUrl":"","sourceName":""},{"idiom":"花好月圆","pinyin":"huā hǎo yuè yuán","meaning":"花儿盛开，月亮圆满，比喻美好圆满的生活，常用来祝福婚姻幸福。","misconception":"常用于美满生活或婚姻的祝福，不只是描写花和月亮。","id":"idiom-104","sourceUrl":"","sourceName":""},{"id":"idiom-105","idiom":"海阔天空","pinyin":"hǎi kuò tiān kōng","meaning":"形容天地广阔，也比喻心胸开阔，或形容想象、谈论不受拘束，范围很广。","misconception":"不只描写海和天，也能形容想象和谈话。","sourceUrl":"https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=-415&la=0&webMd=1","sourceName":"教育部《成语典》：海阔天空"},{"id":"idiom-106","idiom":"海底捞针","pinyin":"hǎi dǐ lāo zhēn","meaning":"像到海底寻找一根针一样，比喻寻找的范围很大，事情极难办到。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-107","idiom":"水落石出","pinyin":"shuǐ luò shí chū","meaning":"水位下降后石头露出来，比喻事情经过调查，真相终于显露出来。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-108","idiom":"水中捞月","pinyin":"shuǐ zhōng lāo yuè","meaning":"到水里捞月亮的影子，比喻所做的事情不可能成功，只是白费力气。","misconception":"不只是困难，而是所用办法注定得不到想要的结果。","sourceUrl":"","sourceName":""},{"id":"idiom-109","idiom":"镜花水月","pinyin":"jìng huā shuǐ yuè","meaning":"镜子里的花、水里的月亮，比喻看似美好却虚幻、无法实际得到的事物。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-110","idiom":"火上浇油","pinyin":"huǒ shàng jiāo yóu","meaning":"往火里再倒油，比喻使别人更加愤怒，或让矛盾和困难进一步加重。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-111","idiom":"雪中送炭","pinyin":"xuě zhōng sòng tàn","meaning":"在下雪的寒冷天气送去取暖的炭，比喻在别人急需时给予实际帮助。","misconception":"重点是帮助处于困难中的人，不是给好事再添一点好处。","sourceUrl":"","sourceName":""},{"id":"idiom-112","idiom":"锦上添花","pinyin":"jǐn shàng tiān huā","meaning":"在美丽的锦缎上再添花纹，比喻让本来已经好的事物变得更好。","misconception":"与雪中送炭不同，原来的情况已经很好。","sourceUrl":"","sourceName":""},{"id":"idiom-113","idiom":"杯水车薪","pinyin":"bēi shuǐ chē xīn","meaning":"用一杯水去救一车着火的柴，比喻力量太小，无法解决严重的问题。","misconception":"“薪”指柴草，不是工资。","sourceUrl":"","sourceName":""},{"id":"idiom-114","idiom":"飞蛾扑火","pinyin":"fēi é pū huǒ","meaning":"飞蛾扑向火焰，比喻自己投向危险，招来灾祸或毁灭。","misconception":"通常带有自找灾祸的意思，不宜直接当作勇敢的赞语。","sourceUrl":"","sourceName":""},{"id":"idiom-115","idiom":"隔岸观火","pinyin":"gé àn guān huǒ","meaning":"隔着河岸看对岸起火，比喻对别人的危难冷眼旁观，不肯给予帮助。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-116","idiom":"破釜沉舟","pinyin":"pò fǔ chén zhōu","meaning":"砸破锅、沉掉船，表示不留退路，比喻下定决心，尽全力干到底。","misconception":"“釜”是锅；重点是决心坚定，不是实际破坏物品。","sourceUrl":"","sourceName":""},{"id":"idiom-117","idiom":"背水一战","pinyin":"bèi shuǐ yī zhàn","meaning":"背靠河水与敌人作战，比喻处在没有退路的境地，决心奋力拼搏。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-118","idiom":"四面楚歌","pinyin":"sì miàn chǔ gē","meaning":"四周传来楚地的歌声，后来比喻陷入四面受敌、孤立无援的困境。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-119","idiom":"草木皆兵","pinyin":"cǎo mù jiē bīng","meaning":"把草和树木都当成敌兵，形容人在极度惊恐时，疑心很重。","misconception":"不是说军队人数很多，而是说人因恐惧产生错觉。","sourceUrl":"","sourceName":""},{"id":"idiom-120","idiom":"负荆请罪","pinyin":"fù jīng qǐng zuì","meaning":"背着荆条向对方认错，表示愿意受责罚，比喻主动而诚恳地承认过错。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-121","idiom":"完璧归赵","pinyin":"wán bì guī zhào","meaning":"把完整的和氏璧送回赵国，后来比喻把物品完好无损地归还原主。","misconception":"“完”指完整；写作玉字旁的“璧”，不是墙壁的“壁”。","sourceUrl":"","sourceName":""},{"id":"idiom-122","idiom":"围魏救赵","pinyin":"wéi wèi jiù zhào","meaning":"通过进攻魏国解除赵国的危急，比喻攻击对方要害，解救另一处的困难。","misconception":"不是直接到受困地点救援，而是设法让对方回头应付。","sourceUrl":"","sourceName":""},{"id":"idiom-123","idiom":"纸上谈兵","pinyin":"zhǐ shàng tán bīng","meaning":"只在纸面上谈论作战，比喻空谈理论，不能把道理用于实际解决问题。","misconception":"批评的是脱离实际的空谈，并不是说理论学习没有用。","sourceUrl":"","sourceName":""},{"id":"idiom-124","idiom":"胸有成竹","pinyin":"xiōng yǒu chéng zhú","meaning":"画竹子前心中已有竹子的形象，比喻做事之前已有成熟的考虑和把握。","misconception":"强调事先已有准备和计划，不是毫无根据地自信。","sourceUrl":"","sourceName":""},{"id":"idiom-125","idiom":"望梅止渴","pinyin":"wàng méi zhǐ kě","meaning":"想到梅子的酸味而暂时缓解口渴，比喻用无法实现的愿望来安慰自己。","misconception":"并没有真正吃到梅子，强调用愿望作自我安慰。","sourceUrl":"","sourceName":""},{"id":"idiom-126","idiom":"卧薪尝胆","pinyin":"wò xīn cháng dǎn","meaning":"睡在柴草上，尝苦胆提醒自己，比喻刻苦自励，立志改变处境、奋发图强。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-127","idiom":"闻风丧胆","pinyin":"wén fēng sàng dǎn","meaning":"听到一点消息就吓得失去勇气，形容对某人或某事非常恐惧。","misconception":"“丧”读sàng，指失去；不是听见风吹的声音。","sourceUrl":"https://www.zdic.net/hans/闻风丧胆","sourceName":"汉典：闻风丧胆"},{"id":"idiom-128","idiom":"打草惊蛇","pinyin":"dǎ cǎo jīng shé","meaning":"打动草丛惊走了蛇，比喻行动不够谨慎，惊动对方，使对方有了防备。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-129","idiom":"抛砖引玉","pinyin":"pāo zhuān yǐn yù","meaning":"用自己的粗浅意见引出别人高明的见解，是表达谦虚的一种说法。","misconception":"常用于谦称自己的意见，不宜用来贬低别人的发言。","sourceUrl":"","sourceName":""},{"id":"idiom-130","idiom":"买椟还珠","pinyin":"mǎi dú huán zhū","meaning":"买下装珍珠的盒子，却把珍珠退还，比喻取舍不当，只重外表而忽视真正有价值的东西。","misconception":"“椟”是盒子；“还”读huán，意思是归还。","sourceUrl":"https://dict.idioms.moe.edu.tw/idiomView.jsp?ID=-200&la=0&webMd=1","sourceName":"教育部《成语典》：买椟还珠"},{"id":"idiom-131","idiom":"郑人买履","pinyin":"zhèng rén mǎi lǚ","meaning":"郑国人买鞋只相信量好的尺码，不肯试脚，比喻拘泥于成规，不顾实际情况。","misconception":"“履”指鞋，重点是死守依据而不看实际。","sourceUrl":"","sourceName":""},{"id":"idiom-132","idiom":"自相矛盾","pinyin":"zì xiāng máo dùn","meaning":"自己的说法或做法前后互相冲突，不能同时成立，彼此抵触。","misconception":"不是指两个人意见不同，而是同一方的言行互相冲突。","sourceUrl":"","sourceName":""},{"id":"idiom-133","idiom":"东施效颦","pinyin":"dōng shī xiào pín","meaning":"东施模仿西施皱眉的样子，比喻不考虑自身条件而盲目模仿，结果反而不好。","misconception":"批评的是盲目模仿，不是反对一切学习和借鉴。","sourceUrl":"","sourceName":""},{"id":"idiom-134","idiom":"南辕北辙","pinyin":"nán yuán běi zhé","meaning":"想往南方去，却驾车向北走，比喻实际行动与想达到的目的完全相反。","misconception":"重点是行动和目的相反，不只是两个人想法不同。","sourceUrl":"","sourceName":""},{"id":"idiom-135","idiom":"南柯一梦","pinyin":"nán kē yī mèng","meaning":"指一场梦，后来常比喻一场空欢喜，或形容荣华富贵虚幻而短暂。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-136","idiom":"梦寐以求","pinyin":"mèng mèi yǐ qiú","meaning":"连睡梦中都在追求，形容对某件事物非常渴望，希望能够得到。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-137","idiom":"废寝忘食","pinyin":"fèi qǐn wàng shí","meaning":"顾不上睡觉，忘记了吃饭，形容对学习或工作十分专心、努力。","misconception":"这是形容专注的说法，不是提倡真的不吃饭、不睡觉。","sourceUrl":"","sourceName":""},{"id":"idiom-138","idiom":"专心致志","pinyin":"zhuān xīn zhì zhì","meaning":"把心思集中在一件事情上，认真投入，不被其他事情分散注意力。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-139","idiom":"聚精会神","pinyin":"jù jīng huì shén","meaning":"把精神和注意力高度集中起来，形容非常专心地做某件事情。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-140","idiom":"全神贯注","pinyin":"quán shén guàn zhù","meaning":"把全部精神都集中在一件事情上，形容注意力非常集中、十分专注。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-141","idiom":"目不转睛","pinyin":"mù bù zhuǎn jīng","meaning":"眼睛一直盯着看，连眼珠也不转动，形容看得十分专注。","misconception":"“转”读zhuǎn；“睛”是眼睛的睛，不是晴天的晴。","sourceUrl":"","sourceName":""},{"id":"idiom-142","idiom":"手舞足蹈","pinyin":"shǒu wǔ zú dǎo","meaning":"双手舞动，两脚跳跃，形容高兴得不知道怎样表达，兴奋到了极点。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-143","idiom":"张牙舞爪","pinyin":"zhāng yá wǔ zhǎo","meaning":"露出牙齿，挥动爪子，形容凶猛的样子，也形容人气势凶恶、猖狂。","misconception":"“爪”在这里读zhǎo，不读zhuǎ。","sourceUrl":"","sourceName":""},{"id":"idiom-144","idiom":"目瞪口呆","pinyin":"mù dèng kǒu dāi","meaning":"睁大眼睛，说不出话来，形容因为惊讶、恐惧等而发愣的样子。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-145","idiom":"愁眉苦脸","pinyin":"chóu méi kǔ liǎn","meaning":"皱着眉头，脸上带着苦恼的神色，形容因忧愁或烦恼而不开心。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-146","idiom":"眉开眼笑","pinyin":"méi kāi yǎn xiào","meaning":"眉头舒展开来，眼睛带着笑意，形容心情愉快、满脸高兴的样子。","misconception":"","sourceUrl":"","sourceName":""},{"id":"idiom-147","idiom":"喜出望外","pinyin":"xǐ chū wàng wài","meaning":"因为遇到了原先没有料到的好事而特别高兴，快乐超出了原来的期待。","misconception":"不只是高兴，还强调好事出乎原来的意料。","sourceUrl":"","sourceName":""},{"id":"idiom-148","idiom":"垂头丧气","pinyin":"chuí tóu sàng qì","meaning":"低着头，失去精神，形容因失败或不顺利而感到失望、沮丧的样子。","misconception":"“丧”读sàng，指失去；不是sāng。","sourceUrl":"","sourceName":""},{"id":"idiom-149","idiom":"心花怒放","pinyin":"xīn huā nù fàng","meaning":"心里像花盛开一样，形容非常高兴，内心充满喜悦。","misconception":"“怒放”指盛开，不是发怒，所以不表示生气。","sourceUrl":"","sourceName":""},{"id":"idiom-150","idiom":"昂首挺胸","pinyin":"áng shǒu tǐng xiōng","meaning":"抬起头，挺起胸膛，形容精神饱满、有自信或无所畏惧的样子。","misconception":"","sourceUrl":"","sourceName":""},{"id":"a500-001","idiom":"龙争虎斗","pinyin":"lóng zhēng hǔ dòu","meaning":"比喻双方力量强大，争斗或竞争十分激烈。"},{"id":"a500-002","idiom":"龙潭虎穴","pinyin":"lóng tán hǔ xué","meaning":"比喻十分危险的地方。"},{"id":"a500-003","idiom":"龙马精神","pinyin":"lóng mǎ jīng shén","meaning":"比喻旺盛的精神和充沛的活力。"},{"id":"a500-004","idiom":"龙凤呈祥","pinyin":"lóng fèng chéng xiáng","meaning":"龙和凤带来吉祥，常用来表示美好祝愿。"},{"id":"a500-005","idiom":"虎背熊腰","pinyin":"hǔ bèi xióng yāo","meaning":"形容人的身体魁梧健壮。"},{"id":"a500-006","idiom":"虎口拔牙","pinyin":"hǔ kǒu bá yá","meaning":"比喻做十分危险的事情。"},{"id":"a500-007","idiom":"虎口余生","pinyin":"hǔ kǒu yú shēng","meaning":"比喻经历极大危险后侥幸活下来。"},{"id":"a500-008","idiom":"虎落平阳","pinyin":"hǔ luò píng yáng","meaning":"比喻有势力的人失去依靠或优势，陷入困境。"},{"id":"a500-009","idiom":"羊入虎口","pinyin":"yáng rù hǔ kǒu","meaning":"比喻弱者落入强敌手中，处境危险。"},{"id":"a500-010","idiom":"羊肠小道","pinyin":"yáng cháng xiǎo dào","meaning":"形容狭窄而弯曲的小路。"},{"id":"a500-011","idiom":"顺手牵羊","pinyin":"shùn shǒu qiān yáng","meaning":"比喻趁着方便随手拿走别人的东西。"},{"id":"a500-012","idiom":"歧路亡羊","pinyin":"qí lù wáng yáng","meaning":"比喻方向过于分散，迷失目标而没有收获。"},{"id":"a500-013","idiom":"杀鸡取卵","pinyin":"shā jī qǔ luǎn","meaning":"比喻只图眼前的小利，损害长远的利益。"},{"id":"a500-014","idiom":"杀鸡儆猴","pinyin":"shā jī jǐng hóu","meaning":"比喻惩罚一个人来警告其他人。"},{"id":"a500-015","idiom":"鸡鸣狗盗","pinyin":"jī míng gǒu dào","meaning":"比喻微不足道的技能，也指偷偷摸摸的行为。"},{"id":"a500-016","idiom":"鸡毛蒜皮","pinyin":"jī máo suàn pí","meaning":"比喻琐碎而不重要的事情。"},{"id":"a500-017","idiom":"鸡犬升天","pinyin":"jī quǎn shēng tiān","meaning":"比喻一个人得势，跟他有关系的人也跟着沾光。"},{"id":"a500-018","idiom":"呆若木鸡","pinyin":"dāi ruò mù jī","meaning":"形容因惊讶或恐惧而发愣的样子。"},{"id":"a500-020","idiom":"牛刀小试","pinyin":"niú dāo xiǎo shì","meaning":"比喻有很大本领的人，先在小事情上略显身手。"},{"id":"a500-021","idiom":"对症下药","pinyin":"duì zhèng xià yào","meaning":"根据病情用药，比喻针对具体问题采取办法。"},{"id":"a500-022","idiom":"汗牛充栋","pinyin":"hàn niú chōng dòng","meaning":"形容藏书非常多。"},{"id":"a500-024","idiom":"马不停蹄","pinyin":"mǎ bù tíng tí","meaning":"比喻一刻也不停留，连续前进或工作。"},{"id":"a500-025","idiom":"马失前蹄","pinyin":"mǎ shī qián tí","meaning":"比喻偶然出现失误或遭受挫折。"},{"id":"a500-027","idiom":"万马奔腾","pinyin":"wàn mǎ bēn téng","meaning":"像无数匹马奔跑跳跃，形容声势浩大。"},{"id":"a500-028","idiom":"万马齐喑","pinyin":"wàn mǎ qí yīn","meaning":"比喻人们都沉默不语的沉闷局面。"},{"id":"a500-029","idiom":"悬崖勒马","pinyin":"xuán yá lè mǎ","meaning":"比喻到了危险边缘及时醒悟，停止错误行动。"},{"id":"a500-030","idiom":"人仰马翻","pinyin":"rén yǎng mǎ fān","meaning":"形容混乱或遭受惨败的样子。"},{"id":"a500-031","idiom":"快马加鞭","pinyin":"kuài mǎ jiā biān","meaning":"比喻加快速度，加紧前进。"},{"id":"a500-032","idiom":"青梅竹马","pinyin":"qīng méi zhú mǎ","meaning":"形容男女从小一起玩耍、亲密无间。"},{"id":"a500-033","idiom":"犬马之劳","pinyin":"quǎn mǎ zhī láo","meaning":"谦称自己愿意为别人效力。"},{"id":"a500-034","idiom":"犬牙交错","pinyin":"quǎn yá jiāo cuò","meaning":"形容交界线像狗牙一样参差相接。"},{"id":"a500-035","idiom":"狗尾续貂","pinyin":"gǒu wěi xù diāo","meaning":"比喻用不好的东西接在好的东西后面，前后不相称。"},{"id":"a500-036","idiom":"狗仗人势","pinyin":"gǒu zhàng rén shì","meaning":"比喻坏人依仗有权势者欺负别人。"},{"id":"a500-037","idiom":"白云苍狗","pinyin":"bái yún cāng gǒu","meaning":"比喻世事变化无常。"},{"id":"a500-038","idiom":"兔死狗烹","pinyin":"tù sǐ gǒu pēng","meaning":"比喻事情成功后，有功的人反而被抛弃或伤害。"},{"id":"a500-039","idiom":"狡兔三窟","pinyin":"jiǎo tù sān kū","meaning":"比喻预先准备多个藏身之处或应对办法。"},{"id":"a500-040","idiom":"动如脱兔","pinyin":"dòng rú tuō tù","meaning":"形容行动十分敏捷。"},{"id":"a500-041","idiom":"抱头鼠窜","pinyin":"bào tóu shǔ cuàn","meaning":"形容狼狈逃跑的样子。"},{"id":"a500-042","idiom":"贼眉鼠眼","pinyin":"zéi méi shǔ yǎn","meaning":"形容神情鬼鬼祟祟。"},{"id":"a500-043","idiom":"投鼠忌器","pinyin":"tóu shǔ jì qì","meaning":"比喻想打击坏人，却顾忌伤及旁边的人或事物。"},{"id":"a500-045","idiom":"鱼贯而入","pinyin":"yú guàn ér rù","meaning":"像游鱼一样一个接着一个进入。"},{"id":"a500-046","idiom":"鱼米之乡","pinyin":"yú mǐ zhī xiāng","meaning":"指盛产鱼和稻米的富饶地方。"},{"id":"a500-047","idiom":"沉鱼落雁","pinyin":"chén yú luò yàn","meaning":"传统上用来形容女子容貌非常美丽。"},{"id":"a500-048","idiom":"如鲠在喉","pinyin":"rú gěng zài hóu","meaning":"像鱼刺卡在喉咙里，比喻心里有话没说出来而不舒服。"},{"id":"a500-049","idiom":"漏网之鱼","pinyin":"lòu wǎng zhī yú","meaning":"比喻侥幸逃脱的人。"},{"id":"a500-052","idiom":"乌合之众","pinyin":"wū hé zhī zhòng","meaning":"指临时聚集、缺乏组织纪律的一群人。"},{"id":"a500-053","idiom":"鸦雀无声","pinyin":"yā què wú shēng","meaning":"形容十分安静，一点声音也没有。"},{"id":"a500-054","idiom":"鸟尽弓藏","pinyin":"niǎo jìn gōng cáng","meaning":"比喻事情成功后，有功的人被抛弃。"},{"id":"a500-055","idiom":"莺歌燕舞","pinyin":"yīng gē yàn wǔ","meaning":"形容春天鸟儿欢唱飞舞的美好景象。"},{"id":"a500-056","idiom":"鹦鹉学舌","pinyin":"yīng wǔ xué shé","meaning":"比喻只是机械地模仿别人的话，没有自己的见解。"},{"id":"a500-057","idiom":"雁过留声","pinyin":"yàn guò liú shēng","meaning":"比喻人应在世间留下好名声。"},{"id":"a500-058","idiom":"鹤发童颜","pinyin":"hè fà tóng yán","meaning":"白发而面色红润，形容老人气色很好。"},{"id":"a500-059","idiom":"风声鹤唳","pinyin":"fēng shēng hè lì","meaning":"形容惊慌疑惧，听到一点动静就害怕。"},{"id":"a500-060","idiom":"鹏程万里","pinyin":"péng chéng wàn lǐ","meaning":"比喻前程远大。"},{"id":"a500-062","idiom":"鸠占鹊巢","pinyin":"jiū zhàn què cháo","meaning":"比喻强占别人的住所或位置。"},{"id":"a500-063","idiom":"鹬蚌相争","pinyin":"yù bàng xiāng zhēng","meaning":"比喻双方争执不下，让第三方有机会得利。"},{"id":"a500-064","idiom":"狼烟四起","pinyin":"láng yān sì qǐ","meaning":"形容战争或战乱在各处发生。"},{"id":"a500-065","idiom":"狼心狗肺","pinyin":"láng xīn gǒu fèi","meaning":"形容心肠狠毒或忘恩负义。"},{"id":"a500-066","idiom":"引狼入室","pinyin":"yǐn láng rù shì","meaning":"比喻把坏人或敌人招进来，给自己带来祸患。"},{"id":"a500-068","idiom":"鹿死谁手","pinyin":"lù sǐ shéi shǒu","meaning":"比喻竞赛或争斗中还不知道谁会获胜。"},{"id":"a500-070","idiom":"沐猴而冠","pinyin":"mù hóu ér guàn","meaning":"比喻徒有外表或地位，却没有相应的品德和能力。"},{"id":"a500-071","idiom":"心猿意马","pinyin":"xīn yuán yì mǎ","meaning":"形容心思不定，不能专心。"},{"id":"a500-072","idiom":"蜂拥而上","pinyin":"fēng yōng ér shàng","meaning":"形容许多人像蜂群一样一齐涌上去。"},{"id":"a500-073","idiom":"蚁穴溃堤","pinyin":"yǐ xué kuì dī","meaning":"比喻小问题不及时处理，可能造成大祸。"},{"id":"a500-074","idiom":"蝇头小利","pinyin":"yíng tóu xiǎo lì","meaning":"比喻很小的利益。"},{"id":"a500-076","idiom":"噤若寒蝉","pinyin":"jìn ruò hán chán","meaning":"形容因害怕而不敢说话。"},{"id":"a500-080","idiom":"风吹草动","pinyin":"fēng chuī cǎo dòng","meaning":"比喻轻微的动静或变化。"},{"id":"a500-081","idiom":"雨后春笋","pinyin":"yǔ hòu chūn sǔn","meaning":"比喻新事物大量而迅速地出现。"},{"id":"a500-082","idiom":"雨过天晴","pinyin":"yǔ guò tiān qíng","meaning":"雨停后天空放晴，也比喻困难或不愉快的事情过去了。"},{"id":"a500-083","idiom":"风卷残云","pinyin":"fēng juǎn cán yún","meaning":"比喻迅速扫除或吃光剩下的东西。"},{"id":"a500-084","idiom":"春风化雨","pinyin":"chūn fēng huà yǔ","meaning":"比喻良好的教育和帮助，像春风春雨一样滋养人。"},{"id":"a500-085","idiom":"春风得意","pinyin":"chūn fēng dé yì","meaning":"形容取得成功后愉快得意的心情。"},{"id":"a500-086","idiom":"春色满园","pinyin":"chūn sè mǎn yuán","meaning":"园中到处是春天的景色，形容欣欣向荣的景象。"},{"id":"a500-087","idiom":"春意盎然","pinyin":"chūn yì àng rán","meaning":"形容春天的气息十分浓厚。"},{"id":"a500-088","idiom":"春寒料峭","pinyin":"chūn hán liào qiào","meaning":"形容初春仍有些寒冷。"},{"id":"a500-089","idiom":"花团锦簇","pinyin":"huā tuán jǐn cù","meaning":"形容五彩缤纷、十分华丽的景象。"},{"id":"a500-090","idiom":"花红柳绿","pinyin":"huā hóng liǔ lǜ","meaning":"形容花木繁盛、色彩鲜艳的春日景色。"},{"id":"a500-091","idiom":"柳暗花明","pinyin":"liǔ àn huā míng","meaning":"形容春景幽美，也比喻困境中出现新的转机。"},{"id":"a500-092","idiom":"落花流水","pinyin":"luò huā liú shuǐ","meaning":"常用来形容被打得大败的样子。"},{"id":"a500-093","idiom":"落英缤纷","pinyin":"luò yīng bīn fēn","meaning":"形容落花纷纷飘下的美丽景象。"},{"id":"a500-094","idiom":"繁花似锦","pinyin":"fán huā sì jǐn","meaning":"繁盛的鲜花像锦缎一样美丽。"},{"id":"a500-095","idiom":"百花齐放","pinyin":"bǎi huā qí fàng","meaning":"各种花一齐开放，也比喻不同风格的作品蓬勃发展。"},{"id":"a500-096","idiom":"百花争艳","pinyin":"bǎi huā zhēng yàn","meaning":"各种花竞相开放，展示美丽。"},{"id":"a500-097","idiom":"万紫千红","pinyin":"wàn zǐ qiān hóng","meaning":"形容百花盛开、色彩绚丽，也比喻丰富多彩。"},{"id":"a500-098","idiom":"草长莺飞","pinyin":"cǎo zhǎng yīng fēi","meaning":"形容春天草木生长、鸟儿飞舞的景象。"},{"id":"a500-099","idiom":"绿草如茵","pinyin":"lǜ cǎo rú yīn","meaning":"形容绿草浓密柔软，像铺开的垫子。"},{"id":"a500-100","idiom":"郁郁葱葱","pinyin":"yù yù cōng cōng","meaning":"形容草木茂盛，也形容生机旺盛的景象。"},{"id":"a500-101","idiom":"层峦叠嶂","pinyin":"céng luán dié zhàng","meaning":"形容山峰重重叠叠，连绵起伏。"},{"id":"a500-102","idiom":"苍翠欲滴","pinyin":"cāng cuì yù dī","meaning":"形容草木浓绿润泽，仿佛要滴出水来。"},{"id":"a500-103","idiom":"枯木逢春","pinyin":"kū mù féng chūn","meaning":"比喻失去生机的事物重新获得活力。"},{"id":"a500-104","idiom":"枯枝败叶","pinyin":"kū zhī bài yè","meaning":"指干枯的树枝和衰败的叶子。"},{"id":"a500-105","idiom":"根深蒂固","pinyin":"gēn shēn dì gù","meaning":"比喻基础深厚，不容易动摇。"},{"id":"a500-106","idiom":"盘根错节","pinyin":"pán gēn cuò jié","meaning":"树根盘绕，枝节交错，比喻事情复杂，难以处理。"},{"id":"a500-107","idiom":"独木难支","pinyin":"dú mù nán zhī","meaning":"比喻一个人的力量难以支撑全局。"},{"id":"a500-108","idiom":"乘风破浪","pinyin":"chéng fēng pò làng","meaning":"比喻克服困难，勇往直前。"},{"id":"a500-109","idiom":"木已成舟","pinyin":"mù yǐ chéng zhōu","meaning":"比喻事情已经成为定局，难以改变。"},{"id":"a500-110","idiom":"入木三分","pinyin":"rù mù sān fēn","meaning":"形容书法笔力强劲，也比喻分析深刻。"},{"id":"a500-111","idiom":"水天一色","pinyin":"shuǐ tiān yī sè","meaning":"形容水面和天空颜色相接，景色辽阔。"},{"id":"a500-112","idiom":"水光山色","pinyin":"shuǐ guāng shān sè","meaning":"指水与山相映的美丽景色。"},{"id":"a500-113","idiom":"山清水秀","pinyin":"shān qīng shuǐ xiù","meaning":"形容山水风景优美。"},{"id":"a500-114","idiom":"江河日下","pinyin":"jiāng hé rì xià","meaning":"比喻情况一天比一天坏。"},{"id":"a500-115","idiom":"山重水复","pinyin":"shān chóng shuǐ fù","meaning":"形容山峦重叠、水流曲折。"},{"id":"a500-116","idiom":"山穷水尽","pinyin":"shān qióng shuǐ jìn","meaning":"比喻陷入绝境，找不到出路。"},{"id":"a500-117","idiom":"山崩地裂","pinyin":"shān bēng dì liè","meaning":"山岳崩塌，大地裂开，形容声势巨大。"},{"id":"a500-118","idiom":"山高水长","pinyin":"shān gāo shuǐ cháng","meaning":"比喻恩德深厚或情谊长久。"},{"id":"a500-119","idiom":"高山流水","pinyin":"gāo shān liú shuǐ","meaning":"比喻知音难得，也形容乐曲高妙。"},{"id":"b500-001","idiom":"喜笑颜开","pinyin":"xǐ xiào yán kāi","meaning":"脸上露出笑容，形容十分高兴。"},{"id":"b500-002","idiom":"兴高采烈","pinyin":"xìng gāo cǎi liè","meaning":"兴致高，精神饱满，形容非常高兴。"},{"id":"b500-003","idiom":"欢天喜地","pinyin":"huān tiān xǐ dì","meaning":"形容十分欢喜、高兴。"},{"id":"b500-004","idiom":"欣喜若狂","pinyin":"xīn xǐ ruò kuáng","meaning":"高兴得像要失去控制，形容极度喜悦。"},{"id":"b500-005","idiom":"喜不自胜","pinyin":"xǐ bù zì shèng","meaning":"高兴得难以承受，形容非常欢喜。"},{"id":"b500-006","idiom":"喜上眉梢","pinyin":"xǐ shàng méi shāo","meaning":"高兴的神情显露在眉眼之间。"},{"id":"b500-007","idiom":"乐不可支","pinyin":"lè bù kě zhī","meaning":"快乐得难以支撑，形容高兴到了极点。"},{"id":"b500-008","idiom":"笑逐颜开","pinyin":"xiào zhú yán kāi","meaning":"笑得脸上舒展开来，形容十分高兴。"},{"id":"b500-009","idiom":"捧腹大笑","pinyin":"pěng fù dà xiào","meaning":"用手捂着肚子大笑，形容笑得很厉害。"},{"id":"b500-010","idiom":"哄堂大笑","pinyin":"hōng táng dà xiào","meaning":"满屋子的人同时大笑起来。"},{"id":"b500-011","idiom":"忍俊不禁","pinyin":"rěn jùn bù jīn","meaning":"忍不住笑了出来。"},{"id":"b500-012","idiom":"破涕为笑","pinyin":"pò tì wéi xiào","meaning":"停止哭泣，转而笑起来。"},{"id":"b500-013","idiom":"哭笑不得","pinyin":"kū xiào bù dé","meaning":"哭也不好，笑也不好，形容处境尴尬或令人无奈。"},{"id":"b500-014","idiom":"泪流满面","pinyin":"lèi liú mǎn miàn","meaning":"眼泪流满脸，形容十分悲伤或激动。"},{"id":"b500-015","idiom":"痛哭流涕","pinyin":"tòng kū liú tì","meaning":"伤心地大哭，眼泪鼻涕一起流下来。"},{"id":"b500-016","idiom":"泣不成声","pinyin":"qì bù chéng shēng","meaning":"哭得说不出完整的话，形容极度悲伤。"},{"id":"b500-017","idiom":"悲喜交集","pinyin":"bēi xǐ jiāo jí","meaning":"悲伤和喜悦的感情同时涌上心头。"},{"id":"b500-018","idiom":"百感交集","pinyin":"bǎi gǎn jiāo jí","meaning":"各种感受交织在一起，形容心情复杂。"},{"id":"b500-019","idiom":"愁眉不展","pinyin":"chóu méi bù zhǎn","meaning":"眉头紧锁，形容忧愁难解。"},{"id":"b500-020","idiom":"忧心忡忡","pinyin":"yōu xīn chōng chōng","meaning":"心事重重，十分忧虑。"},{"id":"b500-021","idiom":"闷闷不乐","pinyin":"mèn mèn bù lè","meaning":"心里烦闷，感到不快乐。"},{"id":"b500-022","idiom":"郁郁寡欢","pinyin":"yù yù guǎ huān","meaning":"心情苦闷，很少露出欢乐的神情。"},{"id":"b500-023","idiom":"忐忑不安","pinyin":"tǎn tè bù ān","meaning":"心里不踏实，紧张而不安定。"},{"id":"b500-024","idiom":"心急如焚","pinyin":"xīn jí rú fén","meaning":"心里像着了火一样，形容非常着急。"},{"id":"b500-025","idiom":"心烦意乱","pinyin":"xīn fán yì luàn","meaning":"心情烦躁，思绪混乱。"},{"id":"b500-026","idiom":"心神不宁","pinyin":"xīn shén bù níng","meaning":"心里不安定，不能集中精神。"},{"id":"b500-027","idiom":"惊慌失措","pinyin":"jīng huāng shī cuò","meaning":"因惊恐慌乱而不知道该怎么办。"},{"id":"b500-028","idiom":"惊魂未定","pinyin":"jīng hún wèi dìng","meaning":"受惊后的心情还没有平静下来。"},{"id":"b500-029","idiom":"大惊失色","pinyin":"dà jīng shī sè","meaning":"惊恐得脸色都变了。"},{"id":"b500-030","idiom":"胆战心惊","pinyin":"dǎn zhàn xīn jīng","meaning":"形容十分害怕，心里恐惧不安。"},{"id":"b500-031","idiom":"心惊肉跳","pinyin":"xīn jīng ròu tiào","meaning":"形容担心灾祸发生而十分恐惧。"},{"id":"b500-032","idiom":"提心吊胆","pinyin":"tí xīn diào dǎn","meaning":"形容十分担心、害怕，放不下心。"},{"id":"b500-033","idiom":"怒气冲冲","pinyin":"nù qì chōng chōng","meaning":"形容满脸怒气，非常生气。"},{"id":"b500-034","idiom":"怒不可遏","pinyin":"nù bù kě è","meaning":"愤怒得无法抑制。"},{"id":"b500-035","idiom":"怒发冲冠","pinyin":"nù fà chōng guān","meaning":"愤怒得头发直竖，形容极其愤怒。"},{"id":"b500-036","idiom":"勃然大怒","pinyin":"bó rán dà nù","meaning":"突然间非常生气。"},{"id":"b500-037","idiom":"大发雷霆","pinyin":"dà fā léi tíng","meaning":"比喻大声斥责，发很大的脾气。"},{"id":"b500-038","idiom":"暴跳如雷","pinyin":"bào tiào rú léi","meaning":"急怒得跳脚，形容脾气发作得很厉害。"},{"id":"b500-039","idiom":"心平气和","pinyin":"xīn píng qì hé","meaning":"心情平静，态度温和。"},{"id":"b500-040","idiom":"平心静气","pinyin":"píng xīn jìng qì","meaning":"使心情平和、情绪安定下来。"},{"id":"b500-041","idiom":"从容不迫","pinyin":"cóng róng bù pò","meaning":"态度镇定，不慌不忙。"},{"id":"b500-042","idiom":"泰然自若","pinyin":"tài rán zì ruò","meaning":"面对异常情况仍然安定镇静，像平常一样。"},{"id":"b500-043","idiom":"镇定自若","pinyin":"zhèn dìng zì ruò","meaning":"遇事沉着冷静，神情和平常一样。"},{"id":"b500-044","idiom":"若无其事","pinyin":"ruò wú qí shì","meaning":"像没有发生什么事一样。"},{"id":"b500-045","idiom":"不动声色","pinyin":"bù dòng shēng sè","meaning":"心里的想法不从声音和神情中流露出来。"},{"id":"b500-046","idiom":"得意忘形","pinyin":"dé yì wàng xíng","meaning":"高兴得失去常态，忘记了应有的分寸。"},{"id":"b500-047","idiom":"洋洋得意","pinyin":"yáng yáng dé yì","meaning":"形容十分得意、自满的样子。"},{"id":"b500-048","idiom":"垂涎三尺","pinyin":"chuí xián sān chǐ","meaning":"口水流得很长，形容极其嘴馋或贪求。"},{"id":"b500-049","idiom":"迫不及待","pinyin":"pò bù jí dài","meaning":"急迫得不能再等待。"},{"id":"b500-050","idiom":"恋恋不舍","pinyin":"liàn liàn bù shě","meaning":"十分留恋，舍不得离开或放下。"},{"id":"b500-051","idiom":"依依不舍","pinyin":"yī yī bù shě","meaning":"十分依恋，不忍分离。"},{"id":"b500-052","idiom":"依依惜别","pinyin":"yī yī xī bié","meaning":"因留恋而舍不得分别。"},{"id":"b500-053","idiom":"难舍难分","pinyin":"nán shě nán fēn","meaning":"感情深厚，舍不得分离。"},{"id":"b500-054","idiom":"念念不忘","pinyin":"niàn niàn bù wàng","meaning":"一直记在心里，没有忘记。"},{"id":"b500-055","idiom":"魂牵梦萦","pinyin":"hún qiān mèng yíng","meaning":"连梦里都在牵挂，形容十分思念。"},{"id":"b500-056","idiom":"大公无私","pinyin":"dà gōng wú sī","meaning":"办事公正，一心为公，不谋私利。"},{"id":"b500-057","idiom":"铁面无私","pinyin":"tiě miàn wú sī","meaning":"坚持公正，不受私情影响。"},{"id":"b500-058","idiom":"光明磊落","pinyin":"guāng míng lěi luò","meaning":"心地坦荡，言行正大光明。"},{"id":"b500-059","idiom":"光明正大","pinyin":"guāng míng zhèng dà","meaning":"言行正当、坦白，没有不可告人的地方。"},{"id":"b500-061","idiom":"堂堂正正","pinyin":"táng táng zhèng zhèng","meaning":"形容光明正大，也形容仪表端正。"},{"id":"b500-062","idiom":"刚正不阿","pinyin":"gāng zhèng bù ē","meaning":"坚强正直，不迎合奉承别人。"},{"id":"b500-063","idiom":"大义凛然","pinyin":"dà yì lǐn rán","meaning":"坚持正义，态度严肃而令人敬畏。"},{"id":"b500-064","idiom":"见义勇为","pinyin":"jiàn yì yǒng wéi","meaning":"看到合乎正义的事情，就勇敢地去做。"},{"id":"b500-065","idiom":"舍己为人","pinyin":"shě jǐ wèi rén","meaning":"为了别人而牺牲自己的利益。"},{"id":"b500-066","idiom":"助人为乐","pinyin":"zhù rén wéi lè","meaning":"把帮助别人当作快乐的事。"},{"id":"b500-067","idiom":"乐善好施","pinyin":"lè shàn hào shī","meaning":"乐于做好事，喜欢帮助有困难的人。"},{"id":"b500-068","idiom":"拾金不昧","pinyin":"shí jīn bù mèi","meaning":"捡到财物不藏起来据为己有。"},{"id":"b500-069","idiom":"诚心诚意","pinyin":"chéng xīn chéng yì","meaning":"心意真诚，没有虚假。"},{"id":"b500-070","idiom":"真心实意","pinyin":"zhēn xīn shí yì","meaning":"心意真实诚恳。"},{"id":"b500-071","idiom":"一诺千金","pinyin":"yī nuò qiān jīn","meaning":"一个承诺价值千金，形容说话算数、信守诺言。"},{"id":"b500-072","idiom":"言而有信","pinyin":"yán ér yǒu xìn","meaning":"说话守信用，答应的事能够做到。"},{"id":"b500-073","idiom":"言行一致","pinyin":"yán xíng yī zhì","meaning":"说的话和做的事相符合。"},{"id":"b500-074","idiom":"表里如一","pinyin":"biǎo lǐ rú yī","meaning":"外在表现和内心想法一致。"},{"id":"b500-075","idiom":"实事求是","pinyin":"shí shì qiú shì","meaning":"从实际情况出发，按事实作出判断。"},{"id":"b500-076","idiom":"脚踏实地","pinyin":"jiǎo tà shí dì","meaning":"比喻做事踏实认真，不浮夸。"},{"id":"b500-077","idiom":"任劳任怨","pinyin":"rèn láo rèn yuàn","meaning":"不怕辛苦，也不怕受到埋怨。"},{"id":"b500-078","idiom":"勤勤恳恳","pinyin":"qín qín kěn kěn","meaning":"形容勤劳踏实，认真负责。"},{"id":"b500-079","idiom":"兢兢业业","pinyin":"jīng jīng yè yè","meaning":"做事谨慎认真，勤恳负责。"},{"id":"b500-080","idiom":"一丝不苟","pinyin":"yī sī bù gǒu","meaning":"连最细小的地方也认真对待，毫不马虎。"},{"id":"b500-081","idiom":"精益求精","pinyin":"jīng yì qiú jīng","meaning":"已经很好了，还要追求更好。"},{"id":"b500-082","idiom":"尽心尽力","pinyin":"jìn xīn jìn lì","meaning":"用尽心思和力量。"},{"id":"b500-083","idiom":"全力以赴","pinyin":"quán lì yǐ fù","meaning":"把全部力量投入到一件事情中。"},{"id":"b500-084","idiom":"不遗余力","pinyin":"bù yí yú lì","meaning":"用尽全部力量，一点也不保留。"},{"id":"b500-085","idiom":"自强不息","pinyin":"zì qiáng bù xī","meaning":"不断努力，使自己变得更强。"},{"id":"b500-086","idiom":"奋发图强","pinyin":"fèn fā tú qiáng","meaning":"振作精神，努力使自己或集体强盛起来。"},{"id":"b500-087","idiom":"力争上游","pinyin":"lì zhēng shàng yóu","meaning":"努力争取进步和先进的地位。"},{"id":"b500-088","idiom":"奋勇当先","pinyin":"fèn yǒng dāng xiān","meaning":"鼓起勇气，争着走在前面。"},{"id":"b500-089","idiom":"勇往直前","pinyin":"yǒng wǎng zhí qián","meaning":"不畏艰难，勇敢地一直向前。"},{"id":"b500-090","idiom":"百折不挠","pinyin":"bǎi zhé bù náo","meaning":"无论遇到多少挫折，都不退缩屈服。"},{"id":"b500-091","idiom":"坚韧不拔","pinyin":"jiān rèn bù bá","meaning":"意志坚定，遇到困难也不动摇。"},{"id":"b500-093","idiom":"知难而进","pinyin":"zhī nán ér jìn","meaning":"明知有困难，仍勇敢地向前。"},{"id":"b500-094","idiom":"迎难而上","pinyin":"yíng nán ér shàng","meaning":"面对困难主动努力克服。"},{"id":"b500-095","idiom":"不屈不挠","pinyin":"bù qū bù náo","meaning":"在压力和困难面前不屈服、不退缩。"},{"id":"b500-096","idiom":"自力更生","pinyin":"zì lì gēng shēng","meaning":"依靠自己的力量发展或改变处境。"},{"id":"b500-097","idiom":"艰苦奋斗","pinyin":"jiān kǔ fèn dòu","meaning":"不怕艰难困苦，坚持努力奋斗。"},{"id":"b500-098","idiom":"勤学苦练","pinyin":"qín xué kǔ liàn","meaning":"认真学习，刻苦练习。"},{"id":"b500-099","idiom":"孜孜不倦","pinyin":"zī zī bù juàn","meaning":"勤奋努力，不知疲倦。"},{"id":"b500-100","idiom":"手不释卷","pinyin":"shǒu bù shì juàn","meaning":"手里总拿着书，形容勤奋好学。"},{"id":"b500-101","idiom":"学而不厌","pinyin":"xué ér bù yàn","meaning":"努力学习而不感到满足。"},{"id":"b500-102","idiom":"不耻下问","pinyin":"bù chǐ xià wèn","meaning":"不以向地位或学问不如自己的人请教为耻。"},{"id":"b500-103","idiom":"虚心好学","pinyin":"xū xīn hào xué","meaning":"谦虚地向别人请教，喜欢学习。"},{"id":"b500-104","idiom":"温故知新","pinyin":"wēn gù zhī xīn","meaning":"温习旧知识，从中获得新的理解。"},{"id":"b500-105","idiom":"举一反三","pinyin":"jǔ yī fǎn sān","meaning":"从一件事推知同类事物，灵活运用所学。"},{"id":"b500-106","idiom":"融会贯通","pinyin":"róng huì guàn tōng","meaning":"把各方面的知识或道理联系起来，得到全面理解。"},{"id":"b500-107","idiom":"触类旁通","pinyin":"chù lèi páng tōng","meaning":"掌握一类事物的规律后，推知同类的其他事物。"},{"id":"b500-108","idiom":"循序渐进","pinyin":"xún xù jiàn jìn","meaning":"按照一定的顺序，逐步前进或提高。"},{"id":"b500-109","idiom":"学以致用","pinyin":"xué yǐ zhì yòng","meaning":"把学到的知识用于实际。"},{"id":"b500-110","idiom":"博学多才","pinyin":"bó xué duō cái","meaning":"学问广博，具有多方面的才能。"},{"id":"b500-111","idiom":"博览群书","pinyin":"bó lǎn qún shū","meaning":"广泛阅读各种书籍。"},{"id":"b500-112","idiom":"才华横溢","pinyin":"cái huá héng yì","meaning":"形容才华充分显露出来。"},{"id":"b500-113","idiom":"才高八斗","pinyin":"cái gāo bā dǒu","meaning":"形容人的文才很高。"},{"id":"b500-114","idiom":"学富五车","pinyin":"xué fù wǔ chē","meaning":"形容读书很多，学问渊博。"},{"id":"b500-115","idiom":"出口成章","pinyin":"chū kǒu chéng zhāng","meaning":"话一说出来就像文章一样，形容文思敏捷。"},{"id":"b500-116","idiom":"妙笔生花","pinyin":"miào bǐ shēng huā","meaning":"比喻文笔出色，写出的文章精彩。"},{"id":"b500-117","idiom":"文思泉涌","pinyin":"wén sī quán yǒng","meaning":"写作的思路像泉水一样不断涌出。"},{"id":"b500-118","idiom":"过目不忘","pinyin":"guò mù bù wàng","meaning":"看过就能记住，形容记忆力强。"},{"id":"b500-119","idiom":"倒背如流","pinyin":"dào bèi rú liú","meaning":"倒过来背也很流利，形容记得非常熟。"},{"id":"b500-120","idiom":"滚瓜烂熟","pinyin":"gǔn guā làn shú","meaning":"形容读书或背诵十分熟练。"},{"id":"c500-001","idiom":"一帆风顺","pinyin":"yī fān fēng shùn","meaning":"船挂满帆顺风行驶，比喻事情进行顺利，没有阻碍。"},{"id":"c500-002","idiom":"一模一样","pinyin":"yī mú yī yàng","meaning":"样子完全相同，没有什么差别。"},{"id":"c500-003","idiom":"一清二楚","pinyin":"yī qīng èr chǔ","meaning":"十分清楚明白，没有含糊的地方。"},{"id":"c500-004","idiom":"一干二净","pinyin":"yī gān èr jìng","meaning":"十分干净，一点也没有剩下。"},{"id":"c500-005","idiom":"一目了然","pinyin":"yī mù liǎo rán","meaning":"看一眼就能明白，形容事物或情况很清楚。"},{"id":"c500-006","idiom":"一望无际","pinyin":"yī wàng wú jì","meaning":"一眼望不到边，形容范围非常辽阔。"},{"id":"c500-007","idiom":"一落千丈","pinyin":"yī luò qiān zhàng","meaning":"形容地位、声誉或状况突然下降得很厉害。"},{"id":"c500-008","idiom":"一日千里","pinyin":"yī rì qiān lǐ","meaning":"一天前进很远，形容发展或进步非常迅速。"},{"id":"c500-009","idiom":"一朝一夕","pinyin":"yī zhāo yī xī","meaning":"一个早晨或一个晚上，形容很短的时间。"},{"id":"c500-010","idiom":"一来二去","pinyin":"yī lái èr qù","meaning":"指交往或接触了几次，时间逐渐过去。"},{"id":"c500-011","idiom":"一分为二","pinyin":"yī fēn wéi èr","meaning":"把一个整体分成两部分，也指从两个方面看待事物。"},{"id":"c500-012","idiom":"一无所有","pinyin":"yī wú suǒ yǒu","meaning":"什么都没有，通常指没有财物或可以依靠的东西。"},{"id":"c500-013","idiom":"一无所获","pinyin":"yī wú suǒ huò","meaning":"一点收获也没有。"},{"id":"c500-014","idiom":"一言为定","pinyin":"yī yán wéi dìng","meaning":"一句话说定了，就不再改变，表示约定算数。"},{"id":"c500-015","idiom":"一言九鼎","pinyin":"yī yán jiǔ dǐng","meaning":"一句话像九鼎那样重，形容说话很有分量和影响力。"},{"id":"c500-016","idiom":"一字千金","pinyin":"yī zì qiān jīn","meaning":"一个字价值千金，形容文章或文字非常精妙珍贵。"},{"id":"c500-017","idiom":"一纸空文","pinyin":"yī zhǐ kōng wén","meaning":"只有文字却没有实际作用或没有得到执行的文件。"},{"id":"c500-018","idiom":"一针见血","pinyin":"yī zhēn jiàn xuè","meaning":"一针就刺出血，比喻说话直接点明问题的关键。"},{"id":"c500-019","idiom":"一应俱全","pinyin":"yī yīng jù quán","meaning":"应该具备的东西全部都有。"},{"id":"c500-020","idiom":"一唱一和","pinyin":"yī chàng yī hè","meaning":"一个先唱，一个应和，比喻两人互相配合呼应。"},{"id":"c500-021","idiom":"两全其美","pinyin":"liǎng quán qí měi","meaning":"做一件事能照顾到两个方面，使双方都满意。"},{"id":"c500-022","idiom":"三长两短","pinyin":"sān cháng liǎng duǎn","meaning":"指意外的灾祸或事故，常用来委婉地指死亡。"},{"id":"c500-023","idiom":"三言两语","pinyin":"sān yán liǎng yǔ","meaning":"很少的几句话，形容话语简短。"},{"id":"c500-024","idiom":"三五成群","pinyin":"sān wǔ chéng qún","meaning":"三个五个聚在一起，形容人们分成一些小群体。"},{"id":"c500-025","idiom":"三头六臂","pinyin":"sān tóu liù bì","meaning":"三个头、六条手臂，原指神奇的本领，后比喻本领很大。"},{"id":"c500-026","idiom":"三更半夜","pinyin":"sān gēng bàn yè","meaning":"指深夜，人们通常已经休息的时候。"},{"id":"c500-027","idiom":"三番五次","pinyin":"sān fān wǔ cì","meaning":"一次又一次，形容次数很多。"},{"id":"c500-028","idiom":"三令五申","pinyin":"sān lìng wǔ shēn","meaning":"多次下令、反复告诫，强调要求必须遵守。"},{"id":"c500-029","idiom":"三足鼎立","pinyin":"sān zú dǐng lì","meaning":"像鼎的三条腿一样相互对立，比喻三方力量并存。"},{"id":"c500-030","idiom":"四通八达","pinyin":"sì tōng bā dá","meaning":"道路通向各个方向，形容交通便利。"},{"id":"c500-031","idiom":"四面八方","pinyin":"sì miàn bā fāng","meaning":"指周围各个方向或各个地方。"},{"id":"c500-032","idiom":"四分五裂","pinyin":"sì fēn wǔ liè","meaning":"分裂成许多部分，形容不完整或不团结。"},{"id":"c500-033","idiom":"四平八稳","pinyin":"sì píng bā wěn","meaning":"形容十分平稳妥当，也形容做事过于稳妥、缺少新意。"},{"id":"c500-034","idiom":"五湖四海","pinyin":"wǔ hú sì hǎi","meaning":"指全国各地，也泛指世界各地。"},{"id":"c500-035","idiom":"五花八门","pinyin":"wǔ huā bā mén","meaning":"比喻事物种类繁多，变化多样。"},{"id":"c500-036","idiom":"五体投地","pinyin":"wǔ tǐ tóu dì","meaning":"两手、两膝和头都伏在地上，形容敬佩到了极点。"},{"id":"c500-037","idiom":"五谷丰登","pinyin":"wǔ gǔ fēng dēng","meaning":"各种粮食作物都获得丰收。"},{"id":"c500-038","idiom":"六神无主","pinyin":"liù shén wú zhǔ","meaning":"形容慌乱得没有主意，不知道该怎么办。"},{"id":"c500-039","idiom":"七嘴八舌","pinyin":"qī zuǐ bā shé","meaning":"许多人争着说话，议论纷纷。"},{"id":"c500-040","idiom":"七手八脚","pinyin":"qī shǒu bā jiǎo","meaning":"许多人一起动手，动作显得忙乱。"},{"id":"c500-041","idiom":"七零八落","pinyin":"qī líng bā luò","meaning":"零散不齐或残缺不全，没有原来的完整样子。"},{"id":"c500-042","idiom":"七拼八凑","pinyin":"qī pīn bā còu","meaning":"把零散的东西勉强拼合、凑在一起。"},{"id":"c500-043","idiom":"八面玲珑","pinyin":"bā miàn líng lóng","meaning":"原形容窗户明亮通透，后多形容处世圆滑、各方面都能应付。"},{"id":"c500-044","idiom":"九死一生","pinyin":"jiǔ sǐ yī shēng","meaning":"经历极大的危险，侥幸保住生命。"},{"id":"c500-045","idiom":"九霄云外","pinyin":"jiǔ xiāo yún wài","meaning":"极高极远的天空，比喻极远的地方，也形容把事情完全忘记。"},{"id":"c500-046","idiom":"十拿九稳","pinyin":"shí ná jiǔ wěn","meaning":"形容很有把握，成功的可能性很大。"},{"id":"c500-047","idiom":"十指连心","pinyin":"shí zhǐ lián xīn","meaning":"十个手指都牵连着心，比喻亲人关系密切、休戚相关。"},{"id":"c500-048","idiom":"十万火急","pinyin":"shí wàn huǒ jí","meaning":"形容事情万分紧急，必须立刻处理。"},{"id":"c500-049","idiom":"百里挑一","pinyin":"bǎi lǐ tiāo yī","meaning":"从许多人或事物中选出一个，形容非常优秀或难得。"},{"id":"c500-051","idiom":"百年大计","pinyin":"bǎi nián dà jì","meaning":"关系长远利益的重要计划。"},{"id":"c500-052","idiom":"百家争鸣","pinyin":"bǎi jiā zhēng míng","meaning":"各种学派或观点自由发表意见，互相讨论。"},{"id":"c500-053","idiom":"千军万马","pinyin":"qiān jūn wàn mǎ","meaning":"形容军队声势浩大，也比喻力量强大、声势壮盛。"},{"id":"c500-054","idiom":"千家万户","pinyin":"qiān jiā wàn hù","meaning":"形容人家很多，泛指广大家庭。"},{"id":"c500-055","idiom":"千言万语","pinyin":"qiān yán wàn yǔ","meaning":"形容有很多话想说或要说。"},{"id":"c500-056","idiom":"千变万化","pinyin":"qiān biàn wàn huà","meaning":"形容变化非常多，没有固定的样子。"},{"id":"c500-057","idiom":"千差万别","pinyin":"qiān chā wàn bié","meaning":"形容差别很多，各不相同。"},{"id":"c500-058","idiom":"千丝万缕","pinyin":"qiān sī wàn lǚ","meaning":"像许多丝线交织，比喻关系复杂或联系细密。"},{"id":"c500-059","idiom":"千山万水","pinyin":"qiān shān wàn shuǐ","meaning":"许多山和河，形容路途遥远、艰难。"},{"id":"c500-060","idiom":"万家灯火","pinyin":"wàn jiā dēng huǒ","meaning":"许多人家亮着灯，形容城镇夜晚的景象。"},{"id":"c500-062","idiom":"万象更新","pinyin":"wàn xiàng gēng xīn","meaning":"各种事物都改变了旧面貌，呈现新的气象。"},{"id":"c500-063","idiom":"万无一失","pinyin":"wàn wú yī shī","meaning":"形容十分有把握，不会出现差错。"},{"id":"c500-065","idiom":"万里长征","pinyin":"wàn lǐ cháng zhēng","meaning":"路途极远的征程，也比喻长期而艰巨的事业。"},{"id":"c500-066","idiom":"半斤八两","pinyin":"bàn jīn bā liǎng","meaning":"旧制半斤等于八两，比喻彼此差不多，常含贬义。"},{"id":"c500-067","idiom":"半信半疑","pinyin":"bàn xìn bàn yí","meaning":"有些相信，又有些怀疑。"},{"id":"c500-068","idiom":"半壁江山","pinyin":"bàn bì jiāng shān","meaning":"国家疆土的一部分，也泛指整体中重要的一半。"},{"id":"c500-069","idiom":"半推半就","pinyin":"bàn tuī bàn jiù","meaning":"一面推辞，一面接受，形容并非完全拒绝。"},{"id":"c500-070","idiom":"成千上万","pinyin":"chéng qiān shàng wàn","meaning":"形容数量非常多。"},{"id":"c500-071","idiom":"接二连三","pinyin":"jiē èr lián sān","meaning":"一个接着一个，连续不断。"},{"id":"c500-072","idiom":"接连不断","pinyin":"jiē lián bù duàn","meaning":"一个接一个地发生或出现，没有中断。"},{"id":"c500-073","idiom":"不计其数","pinyin":"bù jì qí shù","meaning":"无法计算数量，形容非常多。"},{"id":"c500-074","idiom":"屈指可数","pinyin":"qū zhǐ kě shǔ","meaning":"弯着手指就能数清，形容数量很少。"},{"id":"c500-075","idiom":"寥寥无几","pinyin":"liáo liáo wú jǐ","meaning":"数量非常少，没有几个。"},{"id":"c500-076","idiom":"独一无二","pinyin":"dú yī wú èr","meaning":"只有这一个，没有与它相同或可以相比的。"},{"id":"c500-077","idiom":"无穷无尽","pinyin":"wú qióng wú jìn","meaning":"没有尽头，没有限度。"},{"id":"c500-078","idiom":"应有尽有","pinyin":"yīng yǒu jìn yǒu","meaning":"应该有的东西全都有，形容十分齐全。"},{"id":"c500-079","idiom":"空前绝后","pinyin":"kōng qián jué hòu","meaning":"以前没有，后来也难以再有，形容极其罕见。"},{"id":"c500-080","idiom":"前所未有","pinyin":"qián suǒ wèi yǒu","meaning":"以前从来没有发生过或出现过。"},{"id":"c500-081","idiom":"今非昔比","pinyin":"jīn fēi xī bǐ","meaning":"现在已经和过去不同，常指情况发生了很大进步。"},{"id":"c500-082","idiom":"日新月异","pinyin":"rì xīn yuè yì","meaning":"每天每月都有新的变化，形容发展进步很快。"},{"id":"c500-083","idiom":"日积月累","pinyin":"rì jī yuè lěi","meaning":"一天一天、一月一月地不断积累。"},{"id":"c500-084","idiom":"年深日久","pinyin":"nián shēn rì jiǔ","meaning":"形容经历的时间很长。"},{"id":"c500-085","idiom":"天长地久","pinyin":"tiān cháng dì jiǔ","meaning":"像天地存在的时间一样长，形容长久不变。"},{"id":"c500-086","idiom":"天翻地覆","pinyin":"tiān fān dì fù","meaning":"形容变化极大，也形容闹得非常厉害。"},{"id":"c500-087","idiom":"天南地北","pinyin":"tiān nán dì běi","meaning":"形容相隔遥远，也指谈话涉及各个地方和许多话题。"},{"id":"c500-088","idiom":"天涯海角","pinyin":"tiān yá hǎi jiǎo","meaning":"天的边缘、海的尽头，形容极其遥远的地方。"},{"id":"c500-089","idiom":"翻来覆去","pinyin":"fān lái fù qù","meaning":"来回翻动，也形容反复地想或做某件事。"},{"id":"c500-090","idiom":"颠三倒四","pinyin":"diān sān dǎo sì","meaning":"形容说话或做事没有条理，次序混乱。"},{"id":"c500-091","idiom":"横七竖八","pinyin":"héng qī shù bā","meaning":"有的横着，有的竖着，形容放得杂乱无章。"},{"id":"c500-092","idiom":"东倒西歪","pinyin":"dōng dǎo xī wāi","meaning":"向不同方向倾斜，形容站立或摆放不稳。"},{"id":"c500-093","idiom":"左邻右舍","pinyin":"zuǒ lín yòu shè","meaning":"附近居住的邻居。"},{"id":"c500-094","idiom":"左顾右盼","pinyin":"zuǒ gù yòu pàn","meaning":"向左右两边看，形容四处张望。"},{"id":"c500-095","idiom":"前呼后拥","pinyin":"qián hū hòu yōng","meaning":"前面有人吆喝开路，后面有人簇拥，形容随从很多、排场很大。"},{"id":"c500-096","idiom":"大街小巷","pinyin":"dà jiē xiǎo xiàng","meaning":"城镇里的各种街道和巷子，泛指各处。"},{"id":"c500-097","idiom":"大同小异","pinyin":"dà tóng xiǎo yì","meaning":"主要方面相同，只有小部分不同。"},{"id":"c500-098","idiom":"大材小用","pinyin":"dà cái xiǎo yòng","meaning":"把能做大事的人用来做小事，使才能没有充分发挥。"},{"id":"c500-099","idiom":"大惊小怪","pinyin":"dà jīng xiǎo guài","meaning":"对并不特别的事情表现得过分惊讶。"},{"id":"c500-100","idiom":"大海捞针","pinyin":"dà hǎi lāo zhēn","meaning":"在大海里寻找一根针，比喻寻找起来极其困难。"},{"id":"c500-101","idiom":"小题大做","pinyin":"xiǎo tí dà zuò","meaning":"把小事情当成大事情来处理，形容反应或做法过头。"},{"id":"c500-102","idiom":"小巧玲珑","pinyin":"xiǎo qiǎo líng lóng","meaning":"形容东西小而精致，样子灵巧可爱。"},{"id":"c500-103","idiom":"近在咫尺","pinyin":"jìn zài zhǐ chǐ","meaning":"距离非常近，就在眼前。"},{"id":"c500-104","idiom":"遥遥相对","pinyin":"yáo yáo xiāng duì","meaning":"隔着较远的距离互相面对。"},{"id":"c500-105","idiom":"遥遥领先","pinyin":"yáo yáo lǐng xiān","meaning":"远远地走在前面，形容明显超过别人。"},{"id":"c500-106","idiom":"水泄不通","pinyin":"shuǐ xiè bù tōng","meaning":"连水都流不过去，形容拥挤或包围得十分严密。"},{"id":"c500-107","idiom":"门庭若市","pinyin":"mén tíng ruò shì","meaning":"门前和庭院像集市一样热闹，形容来往的人很多。"},{"id":"c500-108","idiom":"高朋满座","pinyin":"gāo péng mǎn zuò","meaning":"尊贵的朋友坐满席位，形容宾客很多。"},{"id":"c500-109","idiom":"济济一堂","pinyin":"jǐ jǐ yī táng","meaning":"许多有才能的人聚集在一起。"},{"id":"c500-110","idiom":"灯火辉煌","pinyin":"dēng huǒ huī huáng","meaning":"形容夜晚灯光明亮、光彩耀眼。"},{"id":"c500-111","idiom":"张灯结彩","pinyin":"zhāng dēng jié cǎi","meaning":"挂起灯笼，系上彩绸，形容节日或喜庆场面的装饰。"},{"id":"c500-112","idiom":"锣鼓喧天","pinyin":"luó gǔ xuān tiān","meaning":"锣鼓声音响亮，形容热闹或声势很大的场面。"},{"id":"c500-114","idiom":"异口同声","pinyin":"yì kǒu tóng shēng","meaning":"不同的人说出相同的话，形容意见一致。"},{"id":"c500-115","idiom":"众说纷纭","pinyin":"zhòng shuō fēn yún","meaning":"大家说法很多，彼此不一致。"},{"id":"c500-116","idiom":"唇齿相依","pinyin":"chún chǐ xiāng yī","meaning":"像嘴唇和牙齿一样互相依靠，比喻关系密切。"},{"id":"c500-117","idiom":"休戚相关","pinyin":"xiū qī xiāng guān","meaning":"喜忧、祸福彼此相连，形容利害关系密切。"},{"id":"c500-118","idiom":"息息相关","pinyin":"xī xī xiāng guān","meaning":"连每一次呼吸都有关联，比喻关系非常密切。"},{"id":"c500-119","idiom":"相辅相成","pinyin":"xiāng fǔ xiāng chéng","meaning":"互相帮助、互相补充，使双方都发挥作用。"},{"id":"c500-120","idiom":"不相上下","pinyin":"bù xiāng shàng xià","meaning":"分不出高低，形容程度或水平差不多。"},{"id":"c500-121","idiom":"平分秋色","pinyin":"píng fēn qiū sè","meaning":"双方各占一半，比喻水平相当、各有长处。"},{"id":"c500-122","idiom":"伯仲之间","pinyin":"bó zhòng zhī jiān","meaning":"形容双方水平接近，难分高下。"},{"id":"c500-123","idiom":"众星捧月","pinyin":"zhòng xīng pěng yuè","meaning":"许多星星衬托着月亮，比喻许多人拥护或围绕着一个人。"},{"id":"c500-124","idiom":"众口难调","pinyin":"zhòng kǒu nán tiáo","meaning":"人们的口味不同，比喻很难使所有人都满意。"},{"id":"c500-125","idiom":"毛遂自荐","pinyin":"máo suì zì jiàn","meaning":"毛遂主动推荐自己承担任务，比喻自己推荐自己。"},{"id":"c500-126","idiom":"班门弄斧","pinyin":"bān mén nòng fǔ","meaning":"在鲁班门前摆弄斧头，比喻在行家面前卖弄本领。"},{"id":"c500-127","idiom":"邯郸学步","pinyin":"hán dān xué bù","meaning":"模仿别人没有学好，反而丢掉了自己原有的本领。"},{"id":"c500-128","idiom":"塞翁失马","pinyin":"sài wēng shī mǎ","meaning":"塞翁丢了马却后来得福，比喻坏事在一定条件下可能变成好事。"},{"id":"c500-129","idiom":"程门立雪","pinyin":"chéng mén lì xuě","meaning":"在老师门外冒雪等候，形容尊敬老师、诚心求学。"},{"id":"c500-130","idiom":"三顾茅庐","pinyin":"sān gù máo lú","meaning":"刘备多次拜访诸葛亮，后比喻诚心诚意地邀请或拜访人才。"}];
